func testBaseElectricalPowerMeasurementInit() {
    let controller = MTRDeviceController()
    let device = MTRDevice(nodeID: n(1), controller: controller)
    let baseDevice: MTRBaseDevice = device
    _ = (device, baseDevice)

    _ = MTRBaseClusterElectricalPowerMeasurement(device: baseDevice, endpointID: n(1), queue: DispatchQueue.global())
}

func testBaseElectricalPowerMeasurementReadFailClosed() {
    let controller = MTRDeviceController()
    let device = MTRDevice(nodeID: n(1), controller: controller)
    let baseDevice: MTRBaseDevice = device
    _ = (device, baseDevice)

    guard let cluster = MTRBaseClusterElectricalPowerMeasurement(device: baseDevice, endpointID: n(1), queue: DispatchQueue.global()) else {
        mtrRequire(false, "MTRBaseClusterElectricalPowerMeasurement init")
        return
    }
    cluster.readAttributeAcceptedCommandList(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeAccuracy(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeActiveCurrent(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeActivePower(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeApparentCurrent(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeApparentPower(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeAttributeList(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeClusterRevision(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeFeatureMap(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeFrequency(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeGeneratedCommandList(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeHarmonicCurrents(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeHarmonicPhases(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeNeutralCurrent(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeNumberOfMeasurementTypes(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributePowerFactor(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributePowerMode(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeRMSCurrent(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeRMSPower(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeRMSVoltage(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeRanges(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeReactiveCurrent(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeReactivePower(completion: { _, err in mtrExpectInvalidState(err) })
    cluster.readAttributeVoltage(completion: { _, err in mtrExpectInvalidState(err) })
}

func testBaseElectricalPowerMeasurementSubscribeFailClosed() {
